'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const imageURL=s=>typeof s==='string'&&(/^(assets\/|data:image\/(png|jpeg|webp);base64,)/.test(s)||/^https:\/\//.test(s))?s:'';
const safeURL=s=>{try{const u=new URL(s);return u.protocol==='https:'?u.href:''}catch{return ''}};
let data, baseData, currentTab='president', currentCity='ankara';
const dialog=$('#dialog');let lastFocus;
function openDialog(content){lastFocus=document.activeElement;$('#dialog-content').innerHTML=content;if(!dialog.open)dialog.showModal();$('.dialog-close').focus()}
$('.dialog-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>lastFocus?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
$('.menu-toggle').onclick=()=>{const open=$('nav').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',open)};
$$('nav a').forEach(a=>a.onclick=()=>{$('nav').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false')});
const slides=[{title:'Birlikte yetişir,<br><em>birlikte değiştiririz.</em>',desc:'İnancıyla kök salan, ilmiyle gelişen, emeğiyle geleceğe yön veren bir gençlik için bir aradayız.',caption:'DOSTLUKLA BAŞLAR.<br><b>KARDEŞLİKLE BÜYÜR.</b>'},{title:'Düşünen gençlik,<br><em>üreten gelecek.</em>',desc:'Okuyarak, sorgulayarak ve birlikte üreterek kendimizi geliştiriyor; yarının sorumluluğunu bugünden üstleniyoruz.',caption:'BİR FİKİRLE BAŞLAR.<br><b>EMEKLE GÜÇLENİR.</b>'},{title:'Aynı idealde,<br><em>yan yana.</em>',desc:'Farklı şehirlerde aynı heyecanı taşıyoruz. Size en yakın il teşkilatımızı bulun, bu yolculuğa siz de katılın.',caption:'AYNI ŞUUR.<br><b>AYNI KARDEŞLİK.</b>'}];
let slide=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,timer;
$('#dots').innerHTML=slides.map((_,i)=>`<button aria-label="${i+1}. slayt" data-slide="${i}"></button>`).join('');
function renderSlide(){const s=slides[slide];$('#slide-title').innerHTML=s.title;$('#slide-desc').textContent=s.desc;$('.photo-caption').innerHTML=s.caption;$('#slide-count').textContent=`0${slide+1} / 03`;$$('[data-slide]').forEach((b,i)=>{b.classList.toggle('active',i===slide);b.setAttribute('aria-pressed',i===slide)});$('#pause').textContent=paused?'▷':'Ⅱ';$('#pause').setAttribute('aria-label',paused?'Slaytları oynat':'Slaytları duraklat')}
function schedule(){clearInterval(timer);if(!paused)timer=setInterval(()=>{if(!dialog.open&&!document.hidden){slide=(slide+1)%slides.length;renderSlide()}},7000)}
function changeSlide(n){slide=(n+slides.length)%slides.length;renderSlide();schedule()}
$('#prev').onclick=()=>changeSlide(slide-1);$('#next').onclick=()=>changeSlide(slide+1);$$('[data-slide]').forEach(b=>b.onclick=()=>changeSlide(Number(b.dataset.slide)));$('#pause').onclick=()=>{paused=!paused;renderSlide();schedule()};renderSlide();schedule();
function portrait(person){const url=imageURL(person.photo);return `<div class="portrait">${url?`<img src="${esc(url)}" alt="${esc(person.name||person.title)}">`:'<span class="silhouette" aria-hidden="true">♙</span><small>FOTOĞRAF ALANI</small>'}</div>`}
function selectCity(id,scroll=false){const b=data.branches.find(x=>x.id===id);if(!b)return;currentCity=id;$('#city-select').value=id;$('#map-label').textContent=b.city;$$('#turkiye > g').forEach(g=>{const selected=(g.id==='istanbul-asya'?'istanbul-avrupa':g.id)===id;g.classList.toggle('selected',selected);g.setAttribute('aria-pressed',selected)});$('#branch-info').innerHTML=`<div class="branch-code">${esc(b.code)}</div><h3>${esc(b.city)}</h3><p>İl Teşkilatı</p>${imageURL(b.photo)?`<img class="branch-photo" src="${esc(imageURL(b.photo))}" alt="${esc(b.name||b.city+' İl Başkanı')}">`:''}<div class="detail-line"><small>İL BAŞKANI</small>${esc(b.name||'Bilgi henüz eklenmedi')}</div><div class="detail-line"><small>ADRES</small>${esc(b.address||'Adres bilgisi henüz eklenmedi')}</div><div class="detail-line"><small>TELEFON</small>${b.phone?`<a href="tel:${esc(b.phone.replace(/[^+\d]/g,''))}">${esc(b.phone)}</a>`:'Telefon bilgisi henüz eklenmedi'}</div>${b.address?`<a class="text-button" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(b.address)}" target="_blank" rel="noopener">Yol tarifi al ↗</a>`:''}`;if(scroll)$('#subeler').scrollIntoView({behavior:'smooth'})}
function management(tab){currentTab=tab;$$('.tabs [data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-selected',b.dataset.tab===tab)});const el=$('#management-content');if(tab==='president'){el.innerHTML=`<div class="president">${portrait(data.president)}<div class="president-copy"><p class="eyebrow">GENEL BAŞKAN</p><h3>${esc(data.president.name||'Genel Başkanımız')}</h3><p>${esc(data.president.bio||'Genel başkanın fotoğrafı, özgeçmişi ve mesajı bu alanda yer alacaktır.')}</p><button class="text-button" id="president-detail">Başkanın mesajı ↗</button></div></div>`;$('#president-detail').onclick=()=>openDialog(`<p class="eyebrow">GENEL BAŞKAN</p><h2>${esc(data.president.name||'Genel Başkanımız')}</h2><p>${esc(data.president.bio||'Başkanın özgeçmişi ve mesajı henüz eklenmedi.')}</p>`)}else if(tab==='board'){el.innerHTML=`<div class="board-grid">${data.board.map(p=>`<button class="person-card" data-person="${p.id}">${portrait(p)}<div class="person-text"><h3>${esc(p.name||p.title+' Başkanlığı')}</h3><p>${esc(p.name?p.title+' Başkanı':'İsim bilgisi eklenecek')}</p><span>↗</span></div></button>`).join('')}</div>`;$$('[data-person]').forEach(b=>b.onclick=()=>personDetail(Number(b.dataset.person)))}else{el.innerHTML='<input class="search" id="branch-search" aria-label="Şube başkanları arasında il ara" placeholder="İl adıyla arayın…"><div class="branch-list" id="branch-list"></div>';function list(q=''){$('#branch-list').innerHTML=data.branches.filter(b=>b.city.toLocaleLowerCase('tr').includes(q.toLocaleLowerCase('tr'))).map(b=>`<button data-branch="${b.id}">${esc(b.city)}<small>${esc(b.name||'Başkan bilgisi eklenecek')}</small></button>`).join('')||'<p>Aramanıza uygun il bulunamadı.</p>';$$('[data-branch]').forEach(b=>b.onclick=()=>selectCity(b.dataset.branch,true))}list();$('#branch-search').oninput=e=>list(e.target.value)}}
function personDetail(id){const p=data.board.find(p=>p.id===id);if(!p)return;openDialog(`<p class="eyebrow">BAŞKANLIK DİVANI</p><h2>${esc(p.name||p.title+' Başkanlığı')}</h2><p>${esc(p.title)} ${p.name?'Başkanı':''}</p><p>${esc(p.bio||'Özgeçmiş bilgisi henüz eklenmedi.')}</p><h3>Başkan Yardımcıları</h3>${p.assistants.length?p.assistants.map(a=>`<div class="assistant-card">${imageURL(a.photo)?`<img src="${esc(imageURL(a.photo))}" alt="${esc(a.name)}">`:''}<div><b>${esc(a.name)}</b><small>${esc(a.title||'Başkan Yardımcısı')}</small></div></div>`).join(''):'<p>Bu başkanlığa bağlı başkan yardımcıları henüz eklenmedi.</p>'}`)}
$$('[data-tab]').forEach(b=>b.addEventListener('click',()=>management(b.dataset.tab)));
const pages={kurumsal:['KURUMSAL','Önce Ahlak ve Maneviyat.','Millî Gençlik Derneği; gençlerin ahlak, maneviyat, ilim ve sorumluluk bilinciyle gelişimini merkeze alır. Birlikte öğrenmeyi, üretmeyi ve toplum için faydalı olmayı önemser.','Çalışma anlayışımız','İnanç, ilim, plan ve program, kadro ve organizasyon, takip ve kontrol, intaç. Bu ilkeler çalışmalarımıza yön verir.'],yayinlar:['YAYINLAR','Gençliğin fikir dünyası.','Millî Gençlik yayınları; fikir, kültür, sanat ve gençlik çalışmalarını bir araya getirir.','Dijital yayınlar','Dergi ve yayın dosyaları bu bölüme eklenecektir.'],erbakan:['DÜŞÜNCE VE MİRAS','Prof. Dr. Necmettin Erbakan','İman, şuur ve emek merkezli gençlik anlayışı üzerine yazılar, okumalar ve kaynaklar.','Okuma alanı','Doğrulanmış yazılar ve kaynak bağlantıları bu bölüme eklenecektir.'],privacy:['GİZLİLİK','Verileriniz hakkında','Bu önizleme ziyaretçilerden form verisi veya ödeme bilgisi toplamaz. Dış bağlantılara geçildiğinde ilgili hizmetin gizlilik koşulları uygulanır.','İçerik taslakları','Taslak düzenleyicisinde kaydedilen içerikler yalnızca kullandığınız tarayıcıda tutulur. Tarayıcı verilerinin silinmesi taslakları kaldırır. Gerçek kişilerin bilgilerini yayımlamadan önce gerekli izinleri alın.']};
$$('[data-page]').forEach(b=>b.onclick=()=>{const p=pages[b.dataset.page];openDialog(`<p class="eyebrow">${p[0]}</p><h2>${p[1]}</h2><p>${p[2]}</p><h3>${p[3]}</h3><p>${p[4]}</p>`)});
$$('[data-activity]').forEach(b=>b.onclick=()=>openDialog(`<p class="eyebrow">FAALİYET ALANLARIMIZ</p><h2>${esc(b.dataset.activity)}</h2><p>${esc(b.querySelector('p').textContent)}</p><h3>Yerel çalışmalarımıza katılın</h3><p>İlinizdeki çalışmalar ve yaklaşan programlar hakkında bilgi almak için il teşkilatınızla iletişime geçebilirsiniz.</p><button class="button primary" id="activity-branch">İl teşkilatını bul ↗</button>`));
dialog.addEventListener('click',e=>{if(e.target.closest('#activity-branch,#volunteer-branch')){dialog.close();$('#subeler').scrollIntoView({behavior:'smooth'})}});
$$('[data-volunteer]').forEach(b=>b.onclick=()=>openDialog('<p class="eyebrow">GÖNÜLLÜLÜK</p><h2>Bu yolculukta yeriniz var.</h2><p>Gönüllülük ve yerel çalışmalar için size en yakın il teşkilatını seçerek iletişim bilgilerine ulaşabilirsiniz.</p><button class="button primary" id="volunteer-branch">İl teşkilatını bul ↗</button>'));
$$('[data-donate]').forEach(b=>b.onclick=()=>{const d=data.donation;openDialog(`<p class="eyebrow">DAYANIŞMA</p><h2>İyiliğe destek olun.</h2><p>Millî Gençlik Derneği gençlik çalışmalarına destek.</p>${d.iban&&d.recipient?`<div class="detail-line"><small>HESAP SAHİBİ</small>${esc(d.recipient)}</div><div class="detail-line"><small>IBAN</small><b>${esc(d.iban)}</b></div><button id="copy-iban" class="button primary">IBAN'ı kopyala</button><p id="copy-status" role="status"></p>`:'<div class="notice">Bağış hesabı henüz tanımlanmadı. Bu önizleme üzerinden ödeme alınmıyor.</div>'}${safeURL(d.paymentUrl)?`<p><a class="button primary" href="${esc(safeURL(d.paymentUrl))}" target="_blank" rel="noopener">Güvenli bağış sayfasına git ↗</a></p>`:''}`);if($('#copy-iban'))$('#copy-iban').onclick=async()=>{try{await navigator.clipboard.writeText(d.iban);$('#copy-status').textContent='IBAN kopyalandı.'}catch{$('#copy-status').textContent='Kopyalanamadı. IBAN’ı seçerek kopyalayabilirsiniz.'}}});
function renderContact(){const c=data.contact;$('#contact-details').innerHTML=`${c.phone?`<p><a href="tel:${esc(c.phone.replace(/[^+\d]/g,''))}">${esc(c.phone)}</a></p>`:''}${c.email?`<p><a href="mailto:${esc(c.email)}">${esc(c.email)}</a></p>`:''}${c.address?`<p>${esc(c.address)}</p>`:''}`}
function persist(){try{localStorage.setItem('mgd-draft-v1',JSON.stringify(data));return true}catch{return false}}
function editor(){openDialog(`<p class="eyebrow">İÇERİK TASLAĞI</p><h2>Bilgilerinizi hazırlayın.</h2><div class="notice">Bu düzenleyici bir yönetim paneli değildir. Değişiklikler yalnızca bu tarayıcıda görünür. JSON dosyasını dışa aktararak site kaynaklarındaki data.json ile değiştirebilir ve yayımlayabilirsiniz.</div><div class="editor"><label>Bölüm</label><select id="edit-kind"><option value="president">Genel Başkan</option><option value="board">Başkanlık Divanı</option><option value="branches">İl Teşkilatları</option><option value="donation">Bağış Bilgileri</option><option value="contact">İletişim</option></select><div id="edit-fields"></div><div class="actions"><button id="save-draft">Taslağı kaydet</button><button id="export-draft">JSON indir</button><button id="reset-draft">Bu tarayıcıdaki taslağı sıfırla</button></div><p class="editor-status" role="status" id="edit-status"></p></div>`);let kind='president',index=0;
 const field=(key,label,value,type='text')=>`<label for="f-${key}">${label}</label>${type==='textarea'?`<textarea id="f-${key}" data-field="${key}">${esc(value)}</textarea>`:`<input id="f-${key}" data-field="${key}" type="${type}" value="${esc(value)}">`}`;
 function record(){return ['board','branches'].includes(kind)?data[kind][index]:data[kind]}
 function fields(){let content='';if(['board','branches'].includes(kind)){content=`<label>Kişi / İl</label><select id="edit-record">${data[kind].map((r,i)=>`<option value="${i}" ${i===index?'selected':''}>${esc(r.city||r.title)}</option>`).join('')}</select>`}const r=record();if(['president','board','branches'].includes(kind))content+=field('name','Ad Soyad',r.name);if(['president','board'].includes(kind))content+=field('bio','Özgeçmiş / Mesaj',r.bio,'textarea');if(kind==='branches')content+=field('address','Adres',r.address)+field('phone','Telefon',r.phone);if(['president','board','branches'].includes(kind))content+=field('photo','Fotoğraf URL’si veya assets/ yolu',r.photo)+'<label for="upload-photo">Fotoğraf yükle (PNG, JPG, WEBP — en fazla 3 MB)</label><input id="upload-photo" type="file" accept="image/png,image/jpeg,image/webp">';if(kind==='board')content+='<label for="assistants">Başkan yardımcıları (her satıra: Ad Soyad | Görev | Fotoğraf URL’si)</label><textarea id="assistants">'+esc(r.assistants.map(a=>[a.name,a.title,a.photo].join(' | ')).join('\n'))+'</textarea>';if(kind==='donation')content+=field('recipient','Hesap Sahibi',r.recipient)+field('iban','IBAN',r.iban)+field('paymentUrl','HTTPS Bağış Sayfası',r.paymentUrl);if(kind==='contact')content+=field('address','Genel Merkez Adresi',r.address)+field('phone','Telefon',r.phone)+field('email','E-posta',r.email,'email');$('#edit-fields').innerHTML=content;if($('#edit-record'))$('#edit-record').onchange=e=>{index=Number(e.target.value);fields()};if($('#upload-photo'))$('#upload-photo').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>3*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type)){$('#edit-status').textContent='PNG, JPG veya WEBP formatında, en fazla 3 MB fotoğraf seçin.';return}try{const bitmap=await createImageBitmap(file),c=document.createElement('canvas'),ratio=Math.min(1,700/bitmap.width,900/bitmap.height);c.width=bitmap.width*ratio;c.height=bitmap.height*ratio;c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);$('#f-photo').value=c.toDataURL('image/webp',.85);bitmap.close();$('#edit-status').textContent='Fotoğraf hazır. Taslağı kaydet düğmesine basın.'}catch{$('#edit-status').textContent='Fotoğraf okunamadı.'}}}
 function save(){const r=record();$$('[data-field]').forEach(f=>r[f.dataset.field]=f.value.trim());if(kind==='board')r.assistants=$('#assistants').value.split('\n').filter(x=>x.trim()).map(x=>{const [name,title='',photo='']=x.split('|').map(s=>s.trim());return{name,title,photo}});const success=persist();selectCity(currentCity);management(currentTab);renderContact();$('#edit-status').textContent=success?'Taslak bu tarayıcıya kaydedildi. Canlı siteyi güncellemek için JSON dosyasını dışa aktarın.':'Tarayıcı kaydı dolu veya kullanılamıyor. Taslağı JSON olarak indirin.';return success}
 $('#edit-kind').onchange=e=>{kind=e.target.value;index=0;fields()};$('#save-draft').onclick=save;$('#export-draft').onclick=()=>{save();const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='data.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};$('#reset-draft').onclick=()=>{if(confirm('Bu tarayıcıdaki taslak değişiklikleri sıfırlansın mı?')){try{localStorage.removeItem('mgd-draft-v1')}catch{}data=structuredClone(baseData);selectCity(currentCity);management(currentTab);renderContact();fields();$('#edit-status').textContent='Taslak sıfırlandı.'}};fields()}
$('#editor-link').onclick=()=>data?editor():openDialog('<h2>İçerikler yüklenemedi.</h2><p>Lütfen sayfayı yenileyin.</p>');$('#year').textContent=new Date().getFullYear();
async function init(){try{const [dr,mr]=await Promise.all([fetch('data.json'),fetch('assets/turkey.svg')]);if(!dr.ok||!mr.ok)throw new Error('assets');baseData=await dr.json();data=structuredClone(baseData);try{const cached=JSON.parse(localStorage.getItem('mgd-draft-v1'));if(cached&&Array.isArray(cached.branches)&&cached.branches.length===81&&Array.isArray(cached.board)&&cached.president&&cached.contact&&cached.donation)data=cached}catch{}$('#map').innerHTML=await mr.text();const known=new Set(data.branches.map(b=>b.id));$$('#turkiye > g').forEach(g=>{const cityId=g.id==='istanbul-asya'?'istanbul-avrupa':g.id;if(!known.has(cityId))return;g.setAttribute('tabindex','0');g.setAttribute('role','button');g.setAttribute('aria-label',g.dataset.iladi+' il teşkilatı');g.onclick=()=>selectCity(cityId);g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectCity(cityId)}};g.onmouseenter=()=>$('#map-label').textContent=g.dataset.iladi;g.onmouseleave=()=>$('#map-label').textContent=data.branches.find(b=>b.id===currentCity).city});data.branches.sort((a,b)=>a.city.localeCompare(b.city,'tr'));$('#city-select').innerHTML=data.branches.map(b=>`<option value="${b.id}">${esc(b.city)}</option>`).join('');$('#city-select').onchange=e=>selectCity(e.target.value);selectCity(currentCity);management(currentTab);renderContact()}catch(e){$('#map').innerHTML='<p>Harita yüklenemedi. Lütfen sayfayı yenileyin.</p>';$('#management-content').innerHTML='<p>İçerikler yüklenemedi. Lütfen sayfayı yenileyin.</p>'}}
init();
